// Config lives here as a node, NOT in n8n Variables ($vars): Variables are a
// licensed feature, and on community n8n they resolve to undefined silently,
// which would send the introduction with an empty CC and still look like a
// success. Edit these three values after import.
return $input.all().map(i => ({ json: { ...i.json,
  SHERIF_EMAIL:      'sherif.hani@energygreenprint.net.au',
  EMAAS_CAMPAIGN_ID: 'PASTE_CAMPAIGN_ID_HERE',
  SLACK_WEBHOOK_URL: 'PASTE_SLACK_WEBHOOK_HERE',
  DEBUG_RAW:         true      // first run: post the raw payload to Slack so
                               // the real field names can be pinned down
}}));

// Instantly nests the useful fields differently per event type, so pull
// them defensively rather than trusting one shape.
const cfg = $input.first().json;
const b = cfg.body ?? cfg;

const campaignId = b.campaign_id ?? b.campaignId ?? b.campaign?.id ?? '';
const email      = b.lead_email ?? b.email ?? b.lead?.email ?? '';
const first      = b.firstName ?? b.first_name ?? b.lead?.first_name ?? '';
const company    = b.companyName ?? b.company_name ?? b.lead?.company_name ?? '';
const eaccount   = b.email_account ?? b.eaccount ?? b.from_email ?? '';
const replyUuid  = b.email_id ?? b.reply_to_uuid ?? b.id ?? '';
const subject    = b.reply_subject ?? b.subject ?? '';
const replyText  = b.reply_text ?? b.reply_text_snippet ?? '';
const status     = String(b.lead_status ?? b.status ?? b.event_type ?? '').toLowerCase();

// Site context comes from the custom variables we set at push time.
const cv   = b.custom_variables ?? b.payload ?? {};
const city = cv.site_city ?? '';
const state = cv.site_state ?? '';
const title = cv.dm_title ?? '';

return [{ json: {
  SHERIF_EMAIL: cfg.SHERIF_EMAIL,
  EMAAS_CAMPAIGN_ID: cfg.EMAAS_CAMPAIGN_ID,
  SLACK_WEBHOOK_URL: cfg.SLACK_WEBHOOK_URL,
  campaignId, email, first, company, eaccount, replyUuid,
  subject, replyText, status, city, state, title,
  site: city ? ` (${city}${state ? ', ' + state : ''})` : ''
}}];

// Fire-once guard. Instantly retries a failed delivery three times, and a
// lead can be re-marked interested by hand, so without this the prospect can
// receive the same introduction more than once.
const staticData = $getWorkflowStaticData('global');
staticData.introduced = staticData.introduced || {};

const key = ($json.email || '').toLowerCase();
if (!key) { return []; }
if (staticData.introduced[key]) {
  return [];            // already introduced, drop silently
}
staticData.introduced[key] = new Date().toISOString();

const first = $json.first || 'there';
const company = $json.company || 'their site';

// Connector framework: Jude is making an introduction, not delivering the
// service. Sherif's credentials are attributed to Sherif. No sign-off, the
// sending account signature carries identity.
const lines = [
  `Hi ${first},`,
  ``,
  `Great. Putting you in touch with Sherif now, copied here.`,
  ``,
  `Sherif Hani runs Energy GreenPrint in Melbourne. He is a chartered electrical engineer with 20 years on industrial sites, and the energy audit is his. He will pick this up from here.`,
  ``,
  `Sherif, ${first} is at ${company}${$json.site}. Over to you.`
];

const html = '<div>' + lines.join('<br />') + '</div>';
return [{ json: { ...$json, introHtml: html, introText: lines.join('\n') } }];

parameters.jsonBody:
={{ JSON.stringify({
  eaccount: $json.eaccount,
  reply_to_uuid: $json.replyUuid,
  subject: $json.subject,
  cc_address_email_list: $json.SHERIF_EMAIL,
  body: { html: $json.introHtml }
}) }}

={{ JSON.stringify({ text: `:handshake: *Intro made* — ${$('Build intro (fire once)').item.json.company}
${$('Build intro (fire once)').item.json.first} (${$('Build intro (fire once)').item.json.title || 'no title'}) <${$('Build intro (fire once)').item.json.email}>
Sherif CC'd on the thread.

_Their reply:_ ${($('Build intro (fire once)').item.json.replyText || '').slice(0, 300)}` }) }}
